/* Storyboards for Generation Z Developers: a storyboard is data (admin/content/storyboards/<slug>.json), the cast is data
 * (admin/content/storyboards/cast.json), and this file draws both, programmatically, as sketchy SVG panels with Rough.js.
 * Nothing is an image file and nothing is generated by a model: a panel is text that can be corrected and redrawn.
 *
 *   StoryboardKit.drawScene(svg, scene, cast, {seed})   one 1600x1000 panel
 *   StoryboardKit.drawCharacter(g, rc, who, x, floor, {pose, mood, flip, scale})
 *   StoryboardKit.deck(root)                            the swipe deck on a storyboard page (keyboard, buttons, swipe)
 *
 * Scene kinds: cover, scene, evidence, punchline, spectrum. A scene's cast entries say who, where (x, 0..1), pose
 * (stand, point, wave, arms-up, shrug, think, sit), mood (neutral, happy, worried, surprised, thinking, determined)
 * and what they say. Everything drawn is tagged so the deck can animate it: strokes draw themselves, people and
 * bubbles arrive in order.
 */
(function () {
  'use strict';
  const NS = 'http://www.w3.org/2000/svg';
  const W = 1600, H = 1000, FLOOR = 900;
  const INK = '#23262b', PAPER = '#fbf7ee';
  const FONT = "'Patrick Hand', 'Comic Neue', 'Comic Sans MS', cursive";
  const TITLE = "'Caveat', 'Patrick Hand', cursive";

  const el = (tag, attrs, parent) => {
    const e = document.createElementNS(NS, tag);
    for (const k in attrs || {}) e.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(e);
    return e;
  };

  // ------------------------------------------------------------ text
  function wrap(text, max) {
    const words = String(text || '').split(/\s+/).filter(Boolean), lines = [];
    let line = '';
    for (const w of words) {
      if ((line + ' ' + w).trim().length > max && line) { lines.push(line); line = w; }
      else line = (line + ' ' + w).trim();
    }
    if (line) lines.push(line);
    return lines;
  }
  function textBlock(parent, lines, x, y, size, opts) {
    opts = opts || {};
    const t = el('text', { x, y, 'font-family': opts.font || FONT, 'font-size': size, fill: opts.fill || INK,
      'text-anchor': opts.anchor || 'start', 'font-weight': opts.weight || 'normal' }, parent);
    lines.forEach((l, i) => { const s = el('tspan', { x, dy: i === 0 ? 0 : size * (opts.lh || 1.18) }, t); s.textContent = l; });
    return t;
  }

  // ------------------------------------------------------------ shapes
  function roundRectPath(x, y, w, h, r) {
    return `M${x + r},${y} H${x + w - r} Q${x + w},${y} ${x + w},${y + r} V${y + h - r} Q${x + w},${y + h} ${x + w - r},${y + h} H${x + r} Q${x},${y + h} ${x},${y + h - r} V${y + r} Q${x},${y} ${x + r},${y} Z`;
  }
  function draw(g, node, cls) { node.classList.add(cls || 'ink'); g.appendChild(node); return node; }

  // ------------------------------------------------------------ the people
  const MOUTH = {
    neutral: (x, y) => `M${x - 9},${y} L${x + 9},${y}`,
    happy: (x, y) => `M${x - 12},${y - 3} Q${x},${y + 12} ${x + 12},${y - 3}`,
    worried: (x, y) => `M${x - 11},${y + 5} Q${x},${y - 6} ${x + 11},${y + 5}`,
    surprised: null,
    thinking: (x, y) => `M${x - 8},${y + 2} Q${x + 2},${y - 2} ${x + 10},${y + 3}`,
    determined: (x, y) => `M${x - 11},${y + 1} Q${x},${y + 5} ${x + 11},${y - 2}`,
  };
  const BROWS = { neutral: [0, 0], happy: [-3, -3], worried: [6, -6], surprised: [-8, -8], thinking: [-6, 4], determined: [7, -7] };

  function arms(pose, sx, sy, len, dir) {
    // returns [[elbow, hand], [elbow, hand]] for the near arm and the far arm, in the figure's local frame
    const d = dir;
    switch (pose) {
      case 'point': return [[[sx + d * 60, sy + 25], [sx + d * 135, sy - 5]], [[sx - d * 22, sy + 70], [sx - d * 14, sy + 140]]];
      case 'wave': return [[[sx + d * 55, sy - 20], [sx + d * 70, sy - 105]], [[sx - d * 22, sy + 70], [sx - d * 14, sy + 140]]];
      case 'arms-up': return [[[sx + d * 50, sy - 40], [sx + d * 75, sy - 120]], [[sx - d * 50, sy - 40], [sx - d * 75, sy - 120]]];
      case 'shrug': return [[[sx + d * 60, sy + 45], [sx + d * 85, sy - 10]], [[sx - d * 60, sy + 45], [sx - d * 85, sy - 10]]];
      case 'think': return [[[sx + d * 45, sy + 70], [sx + d * 18, sy - 25]], [[sx - d * 22, sy + 70], [sx - d * 14, sy + 140]]];
      default: return [[[sx + d * 22, sy + 70], [sx + d * 16, sy + 140]], [[sx - d * 22, sy + 70], [sx - d * 16, sy + 140]]];
    }
  }

  function hair(g, rc, look, hx, hy, r) {
    const c = look.hairColour || '#3b2a20', o = { fill: c, fillStyle: 'solid', stroke: INK, strokeWidth: 2, roughness: 1.2 };
    switch (look.hair) {
      case 'long':
        draw(g, rc.path(`M${hx - r - 6},${hy + r * 1.6} Q${hx - r - 14},${hy - r * 0.2} ${hx - r * 0.2},${hy - r - 6} Q${hx + r + 12},${hy - r - 4} ${hx + r + 6},${hy + r * 1.6} L${hx + r - 6},${hy + r * 1.5} Q${hx + r - 2},${hy - r * 0.2} ${hx},${hy - r * 0.55} Q${hx - r + 2},${hy - r * 0.2} ${hx - r + 6},${hy + r * 1.5} Z`, o)); break;
      case 'curly':
        for (let i = 0; i < 9; i++) { const a = Math.PI * (1.05 + i * 0.11); draw(g, rc.circle(hx + Math.cos(a) * r * 0.95, hy + Math.sin(a) * r * 0.95, r * 0.62, o)); } break;
      case 'bun':
        draw(g, rc.circle(hx, hy - r - 12, r * 0.75, o));
        draw(g, rc.path(`M${hx - r},${hy - 2} Q${hx - r},${hy - r - 4} ${hx},${hy - r - 4} Q${hx + r},${hy - r - 4} ${hx + r},${hy - 2} Q${hx},${hy - r * 0.55} ${hx - r},${hy - 2} Z`, o)); break;
      case 'beanie':
        draw(g, rc.path(`M${hx - r - 4},${hy - 6} Q${hx - r},${hy - r - 22} ${hx},${hy - r - 24} Q${hx + r},${hy - r - 22} ${hx + r + 4},${hy - 6} Z`, Object.assign({}, o, { fill: look.hatColour || '#c0392b' })));
        draw(g, rc.circle(hx, hy - r - 26, 14, Object.assign({}, o, { fill: look.hatColour || '#c0392b' }))); break;
      case 'bald': break;
      default: // short
        draw(g, rc.path(`M${hx - r - 2},${hy + 4} Q${hx - r - 4},${hy - r - 8} ${hx + 2},${hy - r - 8} Q${hx + r + 6},${hy - r - 6} ${hx + r + 2},${hy + 4} Q${hx + 4},${hy - r * 0.45} ${hx - r - 2},${hy + 4} Z`, o));
    }
  }

  function face(g, rc, mood, hx, hy, r, dir) {
    const ex = hx + dir * 6, eo = r * 0.36, [bi, bo] = BROWS[mood] || BROWS.neutral;
    const ink = { stroke: INK, strokeWidth: 2.4, roughness: 0.6 };
    for (const s of [-1, 1]) {
      const x = ex + s * eo;
      el('circle', { cx: x, cy: hy - 2, r: mood === 'surprised' ? 5 : 4, fill: INK, class: 'ink-solid' }, g);
      const inner = s === -dir ? bi : bo; // brows tilt by mood
      draw(g, rc.line(x - 9, hy - 16 + (s < 0 ? inner : -inner) * 0.6, x + 9, hy - 16 + (s < 0 ? -inner : inner) * 0.6, ink));
    }
    const mx = ex, my = hy + r * 0.45;
    if (mood === 'surprised') draw(g, rc.ellipse(mx, my + 2, 14, 18, Object.assign({ fill: '#7a2e2e', fillStyle: 'solid' }, ink)));
    else draw(g, rc.path((MOUTH[mood] || MOUTH.neutral)(mx, my), ink));
  }

  function accessory(g, rc, look, hx, hy, r, dir) {
    const ink = { stroke: INK, strokeWidth: 2.4, roughness: 0.7 };
    if (look.accessory === 'glasses') {
      const ex = hx + dir * 6, eo = r * 0.36;
      draw(g, rc.circle(ex - eo, hy - 2, 22, ink)); draw(g, rc.circle(ex + eo, hy - 2, 22, ink));
      draw(g, rc.line(ex - eo + 11, hy - 3, ex + eo - 11, hy - 3, ink));
    } else if (look.accessory === 'headphones') {
      draw(g, rc.path(`M${hx - r - 4},${hy} Q${hx},${hy - r * 2.1} ${hx + r + 4},${hy}`, Object.assign({}, ink, { strokeWidth: 6 })));
      for (const s of [-1, 1]) draw(g, rc.rectangle(hx + s * (r + 4) - 9, hy - 8, 18, 30, { fill: look.accentColour || '#2d6a4f', fillStyle: 'solid', stroke: INK, strokeWidth: 2 }));
    } else if (look.accessory === 'lanyard') {
      draw(g, rc.path(`M${hx - 18},${hy + r + 10} L${hx},${hy + r + 75} L${hx + 18},${hy + r + 10}`, Object.assign({}, ink, { stroke: look.accentColour || '#1d4ed8' })));
      draw(g, rc.rectangle(hx - 13, hy + r + 75, 26, 34, { fill: '#fff', fillStyle: 'solid', stroke: INK, strokeWidth: 2 }));
    }
  }

  function drawAgent(g, rc, who, x, floor, o) {
    const s = o.scale || 1, c = who.look.colour || '#0f766e', dir = o.flip ? -1 : 1;
    const by = floor - 40 * s, hx = x, hy = floor - 300 * s;
    draw(g, rc.ellipse(x, floor - 4, 150 * s, 22 * s, { fill: 'rgba(0,0,0,.12)', fillStyle: 'solid', stroke: 'none' }), 'shade');
    draw(g, rc.path(`M${x - 60 * s},${by} Q${x},${by + 22 * s} ${x + 60 * s},${by} L${x + 48 * s},${hy + 70 * s} L${x - 48 * s},${hy + 70 * s} Z`, { fill: c, fillStyle: 'hachure', hachureGap: 7, fillWeight: 2, stroke: INK, strokeWidth: 2.4 }));
    draw(g, rc.path(roundRectPath(hx - 85 * s, hy - 60 * s, 170 * s, 120 * s, 24 * s), { fill: '#e6fffa', fillStyle: 'solid', stroke: INK, strokeWidth: 3 }));
    draw(g, rc.line(hx, hy - 60 * s, hx + dir * 12 * s, hy - 100 * s, { stroke: INK, strokeWidth: 2.6 }));
    draw(g, rc.circle(hx + dir * 12 * s, hy - 104 * s, 16 * s, { fill: '#f59e0b', fillStyle: 'solid', stroke: INK }));
    const mood = o.mood || 'happy';
    for (const sx of [-1, 1]) el('rect', { x: hx + sx * 34 * s - 9 * s + dir * 6, y: hy - 24 * s, width: 18 * s, height: mood === 'thinking' ? 8 * s : 26 * s, rx: 4, fill: c, class: 'ink-solid' }, g);
    draw(g, rc.path((MOUTH[mood] || MOUTH.happy)(hx + dir * 6, hy + 28 * s), { stroke: c, strokeWidth: 3.2, roughness: 0.5 }));
    const prompt = el('text', { x: hx - 70 * s, y: hy + 50 * s, 'font-family': 'ui-monospace, Menlo, monospace', 'font-size': 14 * s, fill: c }, g);
    prompt.textContent = '>_';
    const [[e1, h1], [e2, h2]] = arms(o.pose, x + dir * 50 * s, hy + 90 * s, 1, dir);
    for (const [e, h] of [[e1, h1], [e2, h2]]) {
      draw(g, rc.curve([[x + (e === e1 ? dir : -dir) * 48 * s, hy + 90 * s], e, h], { stroke: INK, strokeWidth: 4 }));
      draw(g, rc.circle(h[0], h[1], 18 * s, { fill: c, fillStyle: 'solid', stroke: INK, strokeWidth: 2 }));
    }
    return { headX: hx, headTop: hy - 110 * s };
  }

  function drawCharacter(g, rc, who, x, floor, o) {
    o = o || {};
    if (who.kind === 'agent') return drawAgent(g, rc, who, x, floor, o);
    const s = (o.scale || 1) * (who.look.height || 1), look = who.look, dir = o.flip ? -1 : 1, pose = o.pose || 'stand';
    const sit = pose === 'sit';
    const hipY = floor - (sit ? 120 : 180) * s, shY = hipY - 160 * s, r = 56 * s, hx = x + dir * 4 * s, hy = shY - r - 18 * s;
    const ink = { stroke: INK, strokeWidth: 2.6, roughness: 1 };
    draw(g, rc.ellipse(x, floor - 3, 170 * s, 22 * s, { fill: 'rgba(0,0,0,.12)', fillStyle: 'solid', stroke: 'none' }), 'shade');
    if (sit) {
      draw(g, rc.rectangle(x - 70 * s, hipY + 6 * s, 140 * s, 18 * s, Object.assign({ fill: '#a16207', fillStyle: 'solid' }, ink)));
      draw(g, rc.line(x - 60 * s, hipY + 24 * s, x - 60 * s, floor, ink)); draw(g, rc.line(x + 60 * s, hipY + 24 * s, x + 60 * s, floor, ink));
    }
    // legs
    const legs = { stroke: look.trousers || '#334155', strokeWidth: 16 * s, roughness: 0.8 };
    if (sit) {
      for (const k of [-1, 1]) { draw(g, rc.line(x + k * 18 * s, hipY, x + dir * 70 * s + k * 14 * s, hipY + 6 * s, legs)); draw(g, rc.line(x + dir * 70 * s + k * 14 * s, hipY + 6 * s, x + dir * 74 * s + k * 14 * s, floor - 8, legs)); }
    } else {
      for (const k of [-1, 1]) draw(g, rc.line(x + k * 20 * s, hipY, x + k * 30 * s, floor - 10, legs));
      for (const k of [-1, 1]) draw(g, rc.ellipse(x + k * 34 * s + dir * 8 * s, floor - 8, 40 * s, 16 * s, { fill: INK, fillStyle: 'solid', stroke: INK, roughness: 0.5 }));
    }
    // body
    draw(g, rc.path(`M${x - 55 * s},${shY + 6 * s} Q${x},${shY - 14 * s} ${x + 55 * s},${shY + 6 * s} L${x + 46 * s},${hipY + 8 * s} Q${x},${hipY + 18 * s} ${x - 46 * s},${hipY + 8 * s} Z`,
      { fill: look.shirt || '#2563eb', fillStyle: 'hachure', hachureGap: 6, fillWeight: 2.2, hachureAngle: -40, stroke: INK, strokeWidth: 2.6, roughness: 1.1 }));
    // arms
    const sx = x, sy = shY + 18 * s, a = arms(pose, 0, 0, 1, dir);
    const armInk = { stroke: look.shirt || '#2563eb', strokeWidth: 14 * s, roughness: 0.9 };
    [a[0], a[1]].forEach(([e, h], i) => {
      const start = [sx + (i === 0 ? dir : -dir) * 46 * s, sy];
      const E = [sx + e[0] * s, sy + e[1] * s], Hh = [sx + h[0] * s, sy + h[1] * s];
      draw(g, rc.curve([start, E, Hh], armInk));
      draw(g, rc.circle(Hh[0], Hh[1], 22 * s, { fill: look.skin || '#e0ac69', fillStyle: 'solid', stroke: INK, strokeWidth: 2 }));
    });
    // neck and head
    draw(g, rc.rectangle(hx - 11 * s, hy + r - 6 * s, 22 * s, 26 * s, { fill: look.skin || '#e0ac69', fillStyle: 'solid', stroke: INK, strokeWidth: 2 }));
    if (look.hair === 'long') hair(el('g', {}, g), rc, look, hx, hy, r);
    draw(g, rc.circle(hx, hy, r * 2, { fill: look.skin || '#e0ac69', fillStyle: 'solid', stroke: INK, strokeWidth: 2.6, roughness: 0.8 }));
    if (look.hair !== 'long') hair(g, rc, look, hx, hy, r);
    else draw(g, rc.path(`M${hx - r + 4},${hy - r * 0.35} Q${hx - r * 0.2},${hy - r * 1.15} ${hx + r - 2},${hy - r * 0.4} Q${hx + r * 0.2},${hy - r * 0.8} ${hx - r + 4},${hy - r * 0.35} Z`, { fill: look.hairColour, fillStyle: 'solid', stroke: INK, strokeWidth: 2 }));
    face(g, rc, o.mood || 'neutral', hx, hy, r, dir);
    accessory(g, rc, look, hx, hy, r, dir);
    return { headX: hx, headTop: hy - r - (look.hair === 'bun' || look.hair === 'beanie' ? 40 : 14) * s };
  }

  // ------------------------------------------------------------ bubbles, captions, props
  function bubble(g, rc, text, x, y, tipX, tipY, o) {
    o = o || {};
    const size = o.size || 34, lines = wrap(text, o.max || 24), w = Math.max(...lines.map(l => l.length)) * size * 0.44 + 60, h = lines.length * size * 1.18 + 40;
    const bx = Math.min(Math.max(x - w / 2, 20), W - w - 20), by = Math.max(y - h, 20);
    const box = el('g', { class: 'pop' }, g);
    if (o.thought) {
      draw(box, rc.ellipse(bx + w / 2, by + h / 2, w * 1.12, h * 1.25, { fill: '#fff', fillStyle: 'solid', stroke: INK, strokeWidth: 2.4, roughness: 1.4 }));
      draw(box, rc.circle(tipX + (bx + w / 2 - tipX) * 0.35, by + h + 18, 22, { fill: '#fff', fillStyle: 'solid', stroke: INK }));
      draw(box, rc.circle(tipX + (bx + w / 2 - tipX) * 0.12, tipY - 18, 12, { fill: '#fff', fillStyle: 'solid', stroke: INK }));
    } else {
      const tx = Math.min(Math.max(tipX, bx + 40), bx + w - 40);
      draw(box, rc.path(`${roundRectPath(bx, by, w, h, 26)} M${tx - 22},${by + h - 2} L${tipX},${tipY} L${tx + 22},${by + h - 2}`, { fill: '#fff', fillStyle: 'solid', stroke: INK, strokeWidth: 2.6, roughness: 0.9 }));
      el('rect', { x: tx - 20, y: by + h - 6, width: 40, height: 8, fill: '#fff' }, box);
    }
    textBlock(box, lines, bx + w / 2, by + 20 + size * 0.85, size, { anchor: 'middle' });
    return box;
  }
  function caption(g, rc, text, o) {
    o = o || {};
    const size = o.size || 34, lines = wrap(text, o.max || 44), w = Math.max(...lines.map(l => l.length)) * size * 0.44 + 48, h = lines.length * size * 1.2 + 30;
    const x = o.x == null ? 40 : o.x, y = o.y == null ? 36 : o.y, box = el('g', { class: 'pop' }, g);
    draw(box, rc.rectangle(x, y, w, h, { fill: o.fill || '#fde68a', fillStyle: 'solid', stroke: INK, strokeWidth: 2.4, roughness: 1 }));
    textBlock(box, lines, x + 22, y + 12 + size * 0.9, size);
    return { w, h };
  }
  const PROPS = {
    laptop(g, rc, x, y, s) {
      draw(g, rc.path(`M${x - 70 * s},${y} L${x - 55 * s},${y - 90 * s} L${x + 55 * s},${y - 90 * s} L${x + 70 * s},${y} Z`, { fill: '#cbd5e1', fillStyle: 'solid', stroke: INK, strokeWidth: 2.4 }));
      draw(g, rc.rectangle(x - 85 * s, y, 170 * s, 12 * s, { fill: '#94a3b8', fillStyle: 'solid', stroke: INK }));
      for (let i = 0; i < 3; i++) draw(g, rc.line(x - 40 * s, y - (70 - i * 18) * s, x + (20 - i * 12) * s, y - (70 - i * 18) * s, { stroke: '#0f766e', strokeWidth: 3 }));
    },
    desk(g, rc, x, y, s) {
      draw(g, rc.rectangle(x - 170 * s, y, 340 * s, 20 * s, { fill: '#b45309', fillStyle: 'hachure', stroke: INK, strokeWidth: 2.4 }));
      draw(g, rc.line(x - 150 * s, y + 20 * s, x - 150 * s, FLOOR, { stroke: INK, strokeWidth: 3 })); draw(g, rc.line(x + 150 * s, y + 20 * s, x + 150 * s, FLOOR, { stroke: INK, strokeWidth: 3 }));
    },
    book(g, rc, x, y, s, p) {
      draw(g, rc.rectangle(x - 55 * s, y - 75 * s, 110 * s, 75 * s, { fill: p.colour || '#1e3a8a', fillStyle: 'solid', stroke: INK, strokeWidth: 2.4 }));
      if (p.label) textBlock(g, [p.label], x, y - 30 * s, 20 * s, { anchor: 'middle', fill: '#fff' });
    },
    board(g, rc, x, y, s, p) {
      draw(g, rc.rectangle(x - 230 * s, y - 300 * s, 460 * s, 280 * s, { fill: '#ffffff', fillStyle: 'solid', stroke: INK, strokeWidth: 3 }));
      draw(g, rc.line(x - 150 * s, y - 20 * s, x - 190 * s, FLOOR, { stroke: INK, strokeWidth: 3 })); draw(g, rc.line(x + 150 * s, y - 20 * s, x + 190 * s, FLOOR, { stroke: INK, strokeWidth: 3 }));
      if (p.lines) textBlock(g, p.lines, x - 200 * s, y - 250 * s, 30 * s, { lh: 1.25 });
    },
    phone(g, rc, x, y, s) { draw(g, rc.rectangle(x - 22 * s, y - 80 * s, 44 * s, 80 * s, { fill: '#111827', fillStyle: 'solid', stroke: INK })); },
    sign(g, rc, x, y, s, p) {
      draw(g, rc.line(x, y, x, FLOOR, { stroke: INK, strokeWidth: 4 }));
      draw(g, rc.rectangle(x - 120 * s, y - 70 * s, 240 * s, 70 * s, { fill: p.colour || '#fef3c7', fillStyle: 'solid', stroke: INK, strokeWidth: 2.4 }));
      textBlock(g, [p.label || ''], x, y - 25 * s, 30 * s, { anchor: 'middle' });
    },
  };

  // ------------------------------------------------------------ settings
  function setting(g, rc, name) {
    draw(g, rc.line(0, FLOOR, W, FLOOR, { stroke: INK, strokeWidth: 3, roughness: 2 }), 'ink');
    if (name === 'office' || name === 'interview') {
      draw(g, rc.rectangle(1180, 120, 300, 220, { fill: '#dbeafe', fillStyle: 'cross-hatch', hachureGap: 14, stroke: INK, strokeWidth: 2.4 }), 'scenery');
      draw(g, rc.line(1330, 120, 1330, 340, { stroke: INK, strokeWidth: 2 }), 'scenery');
    } else if (name === 'street') {
      for (let i = 0; i < 5; i++) draw(g, rc.rectangle(60 + i * 310, 300 + (i % 2) * 80, 220, FLOOR - 300 - (i % 2) * 80, { fill: ['#fde2e4', '#e2ece9', '#fff1e6', '#dfe7fd', '#f0efeb'][i], fillStyle: 'hachure', hachureGap: 12, stroke: '#9ca3af', strokeWidth: 2 }), 'scenery');
    } else if (name === 'night') {
      el('rect', { x: 0, y: 0, width: W, height: FLOOR, fill: '#e8ecf6', class: 'scenery' }, g);
      draw(g, rc.circle(1420, 150, 90, { fill: '#fef9c3', fillStyle: 'solid', stroke: INK }), 'scenery');
    } else if (name === 'classroom') {
      draw(g, rc.rectangle(500, 110, 600, 300, { fill: '#14532d', fillStyle: 'solid', stroke: INK, strokeWidth: 3 }), 'scenery');
    }
  }

  // ------------------------------------------------------------ scenes
  function castOf(cast, id) {
    const who = (cast.characters || []).find(c => c.id === id);
    if (!who) throw new Error('storyboard: no character "' + id + '" in the cast');
    return who;
  }
  function people(g, rc, scene, cast, floor, scale) {
    const placed = [];
    (scene.cast || []).forEach((p, i) => {
      const who = castOf(cast, p.who), x = (p.x == null ? (i + 1) / ((scene.cast.length || 1) + 1) : p.x) * W;
      const fig = el('g', { class: 'actor', style: `--d:${0.25 + i * 0.35}s` }, g);
      const head = drawCharacter(fig, rc, who, x, floor, { pose: p.pose, mood: p.mood, flip: p.flip, scale: (p.scale || 1) * (scale || 1) });
      const name = el('text', { x, y: floor + 44, 'font-family': FONT, 'font-size': 26, fill: '#6b7280', 'text-anchor': 'middle', class: 'name' }, fig);
      name.textContent = who.name;
      placed.push({ p, who, x, head, fig });
    });
    placed.forEach((q, i) => {
      if (!q.p.says) return;
      const lift = (q.p.lift || 0) + (i % 2) * 40;
      const b = bubble(g, rc, q.p.says, q.x + (q.p.bubbleDx || 0), q.head.headTop - 40 - lift, q.head.headX, q.head.headTop - 6, { thought: q.p.thinks, max: q.p.max || 24 });
      b.setAttribute('style', `--d:${0.6 + i * 0.5}s`);
    });
    return placed;
  }

  function drawScene(svg, scene, cast, opts) {
    opts = opts || {};
    while (svg.firstChild) svg.removeChild(svg.firstChild);
    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', [scene.caption, scene.punchline, ...(scene.cast || []).map(c => c.says)].filter(Boolean).join(' '));
    const rc = rough.svg(svg, { options: { seed: opts.seed || 7, roughness: 1, bowing: 1.2 } });
    el('rect', { x: 0, y: 0, width: W, height: H, fill: PAPER }, svg);
    const g = el('g', {}, svg);
    const k = scene.kind || 'scene';
    if (k === 'cover') {
      draw(g, rc.rectangle(30, 30, W - 60, H - 60, { stroke: INK, strokeWidth: 4, roughness: 1.6 }));
      textBlock(g, wrap(scene.title, 26), 90, 200, 96, { font: TITLE, weight: 'bold' });
      if (scene.subtitle) textBlock(g, wrap(scene.subtitle, 48), 94, 200 + 96 * Math.ceil(scene.title.length / 26) + 30, 38);
      people(g, rc, scene, cast, FLOOR - 10, 0.72);
    } else if (k === 'punchline') {
      setting(g, rc, scene.setting);
      const lines = wrap(scene.punchline, 28), size = lines.length > 3 ? 64 : 78;
      const t = textBlock(g, lines, W * (scene.cast && scene.cast.length ? 0.6 : 0.5), 220, size, { font: TITLE, anchor: 'middle', weight: 'bold' });
      t.classList.add('pop'); t.setAttribute('style', '--d:.2s');
      const cx = W * (scene.cast && scene.cast.length ? 0.6 : 0.5), half = Math.min(Math.max(...lines.map(l => l.length)) * size * 0.16, 460), uy = 220 + (lines.length - 1) * size * 1.18 + 34;
      draw(g, rc.path(`M${cx - half},${uy} Q${cx},${uy + 26} ${cx + half},${uy - 8}`, { stroke: '#dc2626', strokeWidth: 6, roughness: 1.5 }));
      people(g, rc, scene, cast, FLOOR, 1);
      if (scene.caption) caption(g, rc, scene.caption);
    } else if (k === 'evidence') {
      setting(g, rc, scene.setting);
      people(g, rc, scene, cast, FLOOR, 1);
      const ev = scene.evidence || {}, x = 700, y = 150, w = 840;
      const card = el('g', { class: 'pop', style: '--d:.5s' }, g);
      if (ev.bars) {
        const max = Math.max(...ev.bars.map(b => b.value)), bw = (w - 80) / ev.bars.length;
        draw(card, rc.rectangle(x, y, w, 600, { fill: '#fff', fillStyle: 'solid', stroke: INK, strokeWidth: 2.4 }));
        if (ev.title) textBlock(card, wrap(ev.title, 40), x + 30, y + 52, 34, { weight: 'bold' });
        ev.bars.forEach((b, i) => {
          const bh = 380 * b.value / max, bx = x + 40 + i * bw + bw * 0.15, by = y + 540 - bh;
          draw(card, rc.rectangle(bx, by, bw * 0.7, bh, { fill: b.colour || '#0f766e', fillStyle: 'hachure', hachureGap: 8, fillWeight: 3, stroke: INK, strokeWidth: 2 }));
          textBlock(card, [String(b.shown || b.value)], bx + bw * 0.35, by - 14, 30, { anchor: 'middle', weight: 'bold' });
          textBlock(card, wrap(b.label, 14), bx + bw * 0.35, y + 572, 22, { anchor: 'middle' });
        });
      } else {
        const lines = wrap(ev.quote, 30), h = lines.length * 54 + 170;
        draw(card, rc.rectangle(x, y, w, h, { fill: '#fffdf5', fillStyle: 'solid', stroke: INK, strokeWidth: 2.4 }));
        draw(card, rc.circle(x + w / 2, y + 6, 26, { fill: '#dc2626', fillStyle: 'solid', stroke: INK }));
        textBlock(card, lines.map((l, i) => (i === 0 ? '“' : '') + l + (i === lines.length - 1 ? '”' : '')), x + 44, y + 90, 46);
        textBlock(card, wrap(ev.source || '', 50), x + 44, y + h - 44, 28, { fill: '#6b7280' });
      }
      if (scene.caption) caption(g, rc, scene.caption, { max: 34 });
    } else if (k === 'spectrum') {
      setting(g, rc, scene.setting);
      const stops = scene.stops || [], y = 330;
      draw(g, rc.line(120, y, W - 120, y, { stroke: INK, strokeWidth: 4 }));
      draw(g, rc.path(`M${W - 150},${y - 18} L${W - 110},${y} L${W - 150},${y + 18}`, { stroke: INK, strokeWidth: 4 }));
      stops.forEach((s, i) => {
        const sx = 200 + i * (W - 400) / Math.max(stops.length - 1, 1), st = el('g', { class: 'pop', style: `--d:${0.2 + i * 0.3}s` }, g);
        draw(st, rc.circle(sx, y, 28, { fill: s.colour || '#fde68a', fillStyle: 'solid', stroke: INK, strokeWidth: 2.4 }));
        textBlock(st, [s.label], sx, y - 46, 40, { anchor: 'middle', font: TITLE, weight: 'bold' });
        if (s.note) textBlock(st, wrap(s.note, 18), sx, y + 66, 30, { anchor: 'middle', fill: '#374151' });
      });
      people(g, rc, scene, cast, FLOOR, 0.8);
      if (scene.caption) caption(g, rc, scene.caption);
    } else {
      setting(g, rc, scene.setting);
      (scene.props || []).forEach(p => { const f = PROPS[p.kind]; if (f) f(el('g', { class: 'prop' }, g), rc, p.x * W, p.y == null ? FLOOR : p.y, p.scale || 1, p); });
      people(g, rc, scene, cast, FLOOR, scene.scale || 1);
      if (scene.caption) caption(g, rc, scene.caption);
    }
    if (opts.footer) textBlock(g, [opts.footer], W - 40, H - 30, 22, { anchor: 'end', fill: '#9ca3af' });
    // every rough stroke draws itself when the deck plays the panel
    svg.querySelectorAll('path').forEach(p => { if (p.getAttribute('fill') === 'none' || !p.getAttribute('fill')) p.setAttribute('pathLength', '1'); });
    return svg;
  }

  // ------------------------------------------------------------ the deck
  function deck(root) {
    const data = JSON.parse(root.querySelector('script[type="application/json"]').textContent);
    const track = root.querySelector('.sb-track'), count = root.querySelector('.sb-count'), notes = root.querySelector('.sb-notes');
    const slides = data.storyboard.scenes.map((scene, i) => {
      const sec = document.createElement('section'); sec.className = 'sb-slide'; sec.id = 'scene-' + (i + 1);
      const svg = document.createElementNS(NS, 'svg'); sec.appendChild(svg); track.appendChild(sec);
      drawScene(svg, scene, data.cast, { seed: 11 + i, footer: `${data.storyboard.title} · ${i + 1}/${data.storyboard.scenes.length}` });
      return sec;
    });
    let current = 0;
    const show = (i) => {
      current = Math.max(0, Math.min(slides.length - 1, i));
      slides[current].scrollIntoView({ behavior: 'smooth', inline: 'start', block: 'nearest' });
    };
    const mark = (i) => {
      current = i; count.textContent = `${i + 1} / ${slides.length}`;
      slides.forEach((s, j) => s.classList.toggle('play', j === i));
      const sc = data.storyboard.scenes[i];
      notes.innerHTML = '';
      const p = document.createElement('p'); p.textContent = sc.note || ''; notes.appendChild(p);
      if (sc.source) { const a = document.createElement('p'); a.className = 'dim'; a.textContent = 'Source: ' + sc.source; notes.appendChild(a); }
      if (history.replaceState) history.replaceState(null, '', '#scene-' + (i + 1));
    };
    const io = new IntersectionObserver((es) => es.forEach(e => { if (e.isIntersecting && e.intersectionRatio > 0.6) mark(slides.indexOf(e.target)); }), { root: track, threshold: [0.6] });
    slides.forEach(s => io.observe(s));
    root.querySelector('.sb-prev').onclick = () => show(current - 1);
    root.querySelector('.sb-next').onclick = () => show(current + 1);
    root.querySelector('.sb-full').onclick = () => { const f = root.requestFullscreen || root.webkitRequestFullscreen; if (f) f.call(root); };
    root.querySelector('.sb-notes-toggle').onclick = () => root.classList.toggle('with-notes');
    document.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowRight' || e.key === 'PageDown' || e.key === ' ') { e.preventDefault(); show(current + 1); }
      if (e.key === 'ArrowLeft' || e.key === 'PageUp') { e.preventDefault(); show(current - 1); }
    });
    const start = parseInt((location.hash.match(/scene-(\d+)/) || [])[1] || '1', 10) - 1;
    requestAnimationFrame(() => { slides[start] && slides[start].scrollIntoView({ inline: 'start', block: 'nearest' }); mark(Math.max(0, start)); });
  }

  function castSheet(root) {
    const data = JSON.parse(root.querySelector('script[type="application/json"]').textContent);
    root.querySelectorAll('svg[data-who]').forEach((svg, i) => {
      const who = data.cast.characters.find(c => c.id === svg.dataset.who);
      const poses = (svg.dataset.poses || 'stand').split(',');
      const moods = (svg.dataset.moods || 'neutral').split(',');
      drawScene(svg, { kind: 'scene', setting: 'none', cast: poses.map((p, j) => ({ who: who.id, x: (j + 1) / (poses.length + 1), pose: p, mood: moods[j % moods.length] })) }, data.cast, { seed: 3 + i });
    });
  }

  window.StoryboardKit = { drawScene, drawCharacter, deck, castSheet, W, H };
  document.addEventListener('DOMContentLoaded', () => {
    document.querySelectorAll('.sb-deck').forEach(deck);
    document.querySelectorAll('.sb-cast').forEach(castSheet);
  });
})();
